.gzp-desk{
          Hintergrund:
            radial-gradient(120% 70% bei 50% 0%, rgba(214,178,110,.05), transparent 58%),
            radial-gradient(130% 100% bei 50% 108%, rgba(0,0,0,.34), transparent 62%),
            /* Holzmaserung – weit und unregelmäßig verteilt (alte Haarlinien).
               Es sah aus wie Samt) */
            wiederholender linearer Gradient (92 Grad,
              rgba(0,0,0,.13) 0 3px,
              transparent 3px 17px,
              rgba(255.255.255,.016) 17px 20px,
              transparent 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              transparent 43px 74px),
            /* Verbindungen der Bretter */
            wiederholender linearer Gradient (90 Grad,
              rgba(0,0,0,.42) 0 2px,
              transparent 2px 148px),
            linear-gradient(180deg, #33261a 0 %, #291e13 52 %, #1c150d 100 %);
        }
        .gzp-under{
          Position: absolut;
          Einschub: 0;
          Hintergrund: linearer Farbverlauf (180 Grad, #e6d9b6 0 %, #d6c599 100 %);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), inset 0 0 0 1px rgba(120,90,36,.2);
          transformieren: rotieren(-1,15 Grad) translatorY(5px);
        }
        .gzp-under--2{
          Hintergrund: linearer Farbverlauf (180 Grad, #e1d2ab 0 %, #cfbd90 100 %);
          transformieren: rotieren(.85deg) translatorY(9px);
        }
